const raw = $input.first().json;
let text = '';

if (raw.content && raw.content.parts && raw.content.parts.length > 0) {
    text = raw.content.parts[0].text;
} else {
    text = raw.text || raw.response || '';
}

text = String(text).trim().replace(/^\x60{3}(json)?/i, '').replace(/\x60{3}$/, '').trim();

let data;
try {
    data = JSON.parse(text);
} catch (e) {
    return [{json: {error: 'parse_failed', raw: text}}];
}

const toNum = (v) => Number(String(v ?? '').replace(/[^\d]/g, '')) || 0;

const tanggal = data.tanggal || '';
const toko = data.nama_toko || '';
const total = data.total_pengeluaran || data.total || '';


const diskon = toNum(data.diskon);
const pajak = toNum(data.pajak);

const totalAkhir = data.total_akhir ? toNum(data.total_akhir) : (toNum(total) - diskon + pajak);

const namaBarangStr = String(data.nama_barang || '');
const hargaSatuanStr = String(data.harga_satuan || '');
const kuantitasStr = data.kuantitas_barang || data.kuantitas || '';

const namaBarangArr = namaBarangStr.split(',').map(item => item.trim()).filter(item => item !== '');
const hargaSatuanArr = hargaSatuanStr.split(',').map(item => item.trim()).filter(item => item !== '');
const kuantitasArr = String(kuantitasStr).split(',').map(item => item.trim()).filter(item => item !== '');

if (namaBarangArr.length === 0) {
    return [{
        json: {
            tanggal_pembelian: tanggal,
            nama_toko: toko,
            nama_barang: namaBarangStr,
            kuantitas: kuantitasStr,
            harga_satuan: hargaSatuanStr,
            total_nota: total,
            diskon: diskon,
            pajak: pajak,
            total_akhir: totalAkhir
        }
    }];
}

return namaBarangArr.map((nama, index) => {

    let qty = kuantitasArr[index];
    if (kuantitasArr.length === 1 && namaBarangArr.length > 1) {
        qty = '';
    }

    return {
        json: {
            tanggal_pembelian: tanggal,
            nama_toko: toko,
            nama_barang: nama,
            kuantitas: qty || '1',
            harga_satuan: hargaSatuanArr[index] || '',
            total_nota: index === 0 ? total : '',
            diskon: index === 0 ? diskon : '',
            pajak: index === 0 ? pajak : '',
            total_akhir: index === 0 ? totalAkhir : ''
        }
    };
});

const data = $input.all();

if (data.length === 0) {
    return [{json: {pesan_teks: "Data struk kosong atau gagal diproses."}}];
}

const toNum = (v) => Number(String(v ?? '').replace(/[^\d]/g, '')) || 0;

const tanggal = data[0].json.tanggal_pembelian || "-";
const toko = data[0].json.nama_toko || "-";
const total = data[0].json.total_nota || 0;

const diskon = toNum(data[0].json.diskon);
const pajak = toNum(data[0].json.pajak);
const totalAkhir = data[0].json.total_akhir
    ? toNum(data[0].json.total_akhir)
    : (toNum(total) - diskon + pajak);

const daftarBarang = data.map(item => {
    const qty = item.json.kuantitas || '1';
    const nama = item.json.nama_barang || '-';
    const harga = item.json.harga_satuan || '0';


    return `• ${qty}x ${nama} / Rp ${harga}`;
}).join('\n');


let rincian = `*Total Harga: Rp ${total}*`;
if (diskon > 0) rincian += `\n Diskon: -Rp ${diskon}`;
if (pajak > 0) rincian += `\n Pajak/Biaya: +Rp ${pajak}`;
if (diskon > 0 || pajak > 0) rincian += `\n💳 *Total Bayar: Rp ${totalAkhir}*`;


const pesanAkhir = ` *Pengeluaran Berhasil Dicatat!*\n\n Tanggal: ${tanggal}\n Tempat: ${toko}\n\n *Item(s):*\n${daftarBarang}\n\n${rincian}`;


return [{json: {pesan_teks: pesanAkhir}}];
